-- Expand bufan's local demo data to 20 friends, 7 groups and 40 mock messages.
-- The password is copied inside MySQL from the existing mock account so no hash is exposed.
SET NAMES utf8mb4;
START TRANSACTION;

DELETE FROM message WHERE uuid BETWEEN 'MMOCK000000000000013' AND 'MMOCK000000000000040';
DELETE FROM session WHERE uuid BETWEEN 'SMOCK000000000000009' AND 'SMOCK000000000000027';
DELETE FROM user_contact
WHERE user_id IN ('UMOCK000000000000006','UMOCK000000000000007','UMOCK000000000000008','UMOCK000000000000009','UMOCK000000000000010','UMOCK000000000000011','UMOCK000000000000012','UMOCK000000000000013','UMOCK000000000000014','UMOCK000000000000015','UMOCK000000000000016','UMOCK000000000000017','UMOCK000000000000018','UMOCK000000000000019','UMOCK000000000000020')
