DELETE FROM group_info WHERE uuid IN ('GMOCK000000000000004','GMOCK000000000000005','GMOCK000000000000006','GMOCK000000000000007');
DELETE FROM user_info WHERE uuid BETWEEN 'UMOCK000000000000006' AND 'UMOCK000000000000020';

